const digest = $input.first().json;
const today = new Date().toLocaleDateString('en-IN', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'Asia/Kolkata' });

const html = `
<!DOCTYPE html>
<html>
<head><meta charset='utf-8'><style>
  body { font-family: Arial, sans-serif; background: #0a0a0f; color: #e8e8f0; max-width: 600px; margin: 0 auto; padding: 20px; }
  h1 { color: #7f6fff; border-bottom: 2px solid #7f6fff; padding-bottom: 10px; }
  h2 { color: #4dffa0; margin-top: 24px; }
  .metric { background: #111118; border-radius: 8px; padding: 12px; margin: 8px 0; border-left: 3px solid #7f6fff; }
  .task { background: #1a1a24; border-radius: 6px; padding: 10px; margin: 6px 0; }
  .status-ok { color: #4dffa0; } .status-warn { color: #ff6b6b; }
  footer { color: #4a4a60; font-size: 12px; margin-top: 30px; }
</style></head>
<body>
<h1>🤖 Yaazhi Daily Digest</h1>
<p>${today}</p>

<h2>📋 Tasks Completed</h2>
${(digest.tasks_completed || []).map(t => `<div class='task'>✅ ${t}</div>`).join('') || '<p>No tasks completed</p>'}

<h2>🧠 Memories Added</h2>
<div class='metric'>New memories: <strong>${digest.memories_added || 0}</strong> | Total: <strong>${digest.total_memories || 0}</strong></div>

<h2>🏥 System Health</h2>
${Object.entries(digest.system_health || {}).map(([k,v]) => `<div class='metric'>${k}: <span class='${v === 'ok' ? 'status-ok' : 'status-warn'}'>${v === 'ok' ? '✅ OK' : '❌ ' + v}</span></div>`).join('')}

<h2>📅 Upcoming</h2>
${(digest.upcoming || []).map(u => `<div class='task'>🔔 ${u}</div>`).join('') || '<p>Nothing scheduled</p>'}

<footer>Yaazhi AI Operating System | VIT-AP | Santhosh | Generated ${new Date().toISOString()}</footer>
</body></html>`;

return [{ json: { html, subject: `Yaazhi Daily Digest — ${today}`, to: $vars.OWNER_EMAIL } }];
